import { clamp01 } from '../core/contracts.js';
const MAP=Object.freeze({demand:'demandSignal',novelty:'noveltySignal',relation:'relationSignal',diversity:'diversitySignal',dwell:'dwellSignal',weather:'weatherSuitability',accessibility:'accessibilitySignal'});
export function buildDiscoveryFeatures(rows=[],{subjectId}={}){const out={subjectId,features:{},sources:{},coverage:0};for(const row of rows){if(row.subjectId!==subjectId)continue;const key=MAP[row.featureKey];if(!key)continue;if(row.value===null||row.value===undefined)continue;const v=typeof row.value==='number'?clamp01(row.value):null;if(v===null)continue;const prev=out.sources[key];if(!prev||Date.parse(row.validAt||0)>Date.parse(prev.validAt||0)){out.features[key]=v;out.sources[key]={sourceId:row.sourceId,evidenceKind:row.evidenceKind,validAt:row.validAt,confidence:clamp01(row.confidence??1)};}}out.coverage=Object.keys(out.features).length/Object.keys(MAP).length;return out;}
